<?php
require_once "db.php";$users=new UserRepository($pdo);$error="";$success="";$name="";$email="";
if($_SERVER["REQUEST_METHOD"]==="POST"){$name=trim($_POST["name"]??"");$email=trim($_POST["email"]??"");$pass=$_POST["password"]??"";$confirm=$_POST["confirm_password"]??"";
if($name==="")$error="Please enter your name.";elseif(!filter_var($email,FILTER_VALIDATE_EMAIL))$error="Enter a valid email.";elseif(!preg_match("/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[^A-Za-z\d]).{8,}$/",$pass))$error="Password needs 8 characters, upper/lowercase, a number and a symbol.";elseif($pass!==$confirm)$error="Passwords do not match.";elseif($users->emailExists($email))$error="This email is already registered.";else{$users->createUser($name,$email,password_hash($pass,PASSWORD_DEFAULT));$success="Account created. You can log in.";$name=$email="";}}
?>
